/**
 * Builds apps/web/src/lib/legal-docs.generated.ts from docs/legal/textos/04 and 05, so the public /privacidad and
 * /terminos pages always show the approved text without reading the docs folder at runtime (Vercel does not ship it).
 * Run: npm run legal:docs   (a test fails when the generated file is out of date).
 * Internal review notes in backticks, such as `[no verificado]`, are removed from the public text.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

function between(md: string, start: RegExp, end: RegExp | null): string {
  const lines = md.split("\n");
  const from = lines.findIndex((l) => start.test(l));
  if (from < 0) throw new Error(`Heading not found: ${start}`);
  let to = lines.length;
  if (end) for (let i = from + 1; i < lines.length; i++) if (end.test(lines[i]!)) { to = i; break; }
  return lines.slice(from + 1, to).join("\n").trim();
}

function publicText(md: string): string {
  return md
    .replace(/\s*`\[[^`]*\]`/g, "")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

export interface LegalDocs {
  privacy: Record<"es" | "es-es" | "en", string>;
  terms: Record<"es" | "es-es" | "en", string>;
}

export function buildLegalDocs(): LegalDocs {
  const priv = readFileSync(resolve(root, "docs/legal/textos/04-politica-privacidad.md"), "utf8");
  const terms = readFileSync(resolve(root, "docs/legal/textos/05-terminos-y-reembolso.md"), "utf8");

  const privEs = between(priv, /^## A\. /, /^## B\. /).replace(/^---\s*$/gm, "");
  const privEn = between(priv, /^## B\. /, /^## C\. /).replace(/^---\s*$/gm, "");
  const table = between(priv, /^## C\. /, /^## D\. /);
  const module = between(priv, /^### santa y Reyes Magos/, /^### rex/);
  const retention = between(priv, /^### Tabla de retenci/, /^---\s*$/);
  const esVariant = between(priv, /^## E\. /, /^### Variante es-419 para M/);

  const termsEs = between(terms, /^## A\. /, /^## B\. /);
  const termsEn = between(terms, /^## B\. /, /^## C\. /);
  const termsModule = (terms.split("\n").find((l) => l.startsWith("- santa y Reyes Magos:")) ?? "").replace(/^- santa y Reyes Magos: "?/, "").replace(/"$/, "");

  const privacy = {
    es: publicText(`${privEs}\n\n## Proveedores\n\n${table}\n\n## Llamadas de Santa y Reyes Magos\n\n${module}\n\n## Plazos de conservación\n\n${retention}`),
    "es-es": publicText(`${privEs}\n\n## Proveedores\n\n${table}\n\n## Llamadas de Papá Noel y Reyes Magos\n\n${module}\n\n## Plazos de conservación\n\n${retention}\n\n## Adaptación para España\n\n${esVariant}`),
    en: publicText(`${privEn}\n\n## Providers\n\n${table}\n\n## Calls from Santa\n\n${module}\n\n## Retention\n\n${retention}`),
  };
  const termsOut = {
    es: publicText(`${termsEs}\n\n## Llamadas de Santa\n\n${termsModule}`),
    "es-es": publicText(`${termsEs}\n\n## Llamadas de Papá Noel\n\n${termsModule}`),
    en: publicText(`${termsEn}\n\n## Santa calls\n\n${termsModule}`),
  };
  return { privacy, terms: termsOut };
}

export function render(): string {
  return `// GENERATED by scripts/legal-docs.ts from docs/legal/textos/04 and 05. Do not edit: run \`npm run legal:docs\`.\nexport const LEGAL_DOCS = ${JSON.stringify(buildLegalDocs(), null, 2)} as const;\n`;
}

export const OUT = resolve(root, "apps/web/src/lib/legal-docs.generated.ts");

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUT, render());
  console.log(`wrote ${OUT}`);
}
